ss="hidden text-sm font-semibold">Category<select name="category_id" class="mt-1 min-h-11 w-full rounded-lg border-slate-300 dark:border-slate-700 dark:bg-slate-950"><option value="">Choose category</option>@foreach($categories as $category)<option value="{{$category->id}}">{{$category->name}}</option>@endforeach</select></label><label class="text-sm font-semibold">Due date <span class="font-normal text-slate-400">optional</span><input type="date" name="due_date" class="mt-1 min-h-11 w-full rounded-lg border-slate-300 dark:border-slate-700 dark:bg-slate-950"></label></div></section>
