<script>document.addEventListener('DOMContentLoaded',()=>{const type=document.getElementById('count-type');const update=()=>{document.getElementById('category-field').classList.toggle('hidden',type.value!=='category');document.getElementById('product-field').classList.toggle('hidden',!['selected','cycle'].includes(type.value));};type.addEventListener('change',update);update();document.getElementById('count-warehouse').addEventListener('change',event=>{const select=document.getElementById('count-location');[...select.options].forEach((option,index)=>{if(index)option.hidden=option.dataset.warehouse!==event.target.value;});select.value='';});});</script>
